using System;using System.IO;using System.Linq;using NUnit.Framework;using UnityEngine;
namespace ZeroToMillionaire.Tests {
 public sealed class SaveRecoveryTests {
  sealed class Codec:IStateCodec { public string Encode(PlayerState state){return JsonUtility.ToJson(state);}public PlayerState Decode(string text){return JsonUtility.FromJson<PlayerState>(text);} }
  string dir,path;Codec codec;
  [SetUp] public void Before(){dir=Path.Combine(Path.GetTempPath(),"ztm-save-recovery-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);path=Path.Combine(dir,"save.json");codec=new Codec();}
  [TearDown] public void After(){Directory.Delete(dir,true);}
  string Good(int cash=123){return codec.Encode(new PlayerState{cash=cash,spins=9});}
  [TestCase(false)][TestCase(true)] public void UnsupportedPrimaryCannotBeOverwrittenEvenWithValidBackup(bool validBackup){
   var future=new PlayerState{version=Economy.SaveVersion+1,cash=123};string original=codec.Encode(future),backup=validBackup?Good():"broken backup";File.WriteAllText(path,original);File.WriteAllText(path+".bak",backup);
   var store=new SaveStore(path,codec);var app=new GameSession(store,new SeededRandom(1));Assert.IsTrue(app.RecoveryRequired);Assert.IsFalse(app.Save());Assert.IsFalse(app.TryBeginSpin(out _));Assert.IsFalse(app.TrySetTutorial(new TutorialState{skipped=true}));Assert.AreEqual(original,File.ReadAllText(path));Assert.AreEqual(backup,File.ReadAllText(path+".bak"));
  }
  [Test] public void TwoUnreadableFilesStayIntactAcrossPauseQuitEquivalentSave(){File.WriteAllText(path,"broken primary");File.WriteAllText(path+".bak","broken backup");var app=new GameSession(new SaveStore(path,codec),new SeededRandom(1));Assert.IsTrue(app.RecoveryRequired);for(int i=0;i<3;i++)Assert.IsFalse(app.Save());Assert.AreEqual("broken primary",File.ReadAllText(path));Assert.AreEqual("broken backup",File.ReadAllText(path+".bak"));}
  [Test] public void TransientReadFailureRequiresSuccessfulExplicitReload(){string original=Good();File.WriteAllText(path,original);var store=new SaveStore(path,codec);GameSession app;using(var held=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.None)){app=new GameSession(store,new SeededRandom(1));Assert.IsTrue(app.RecoveryRequired);}Assert.IsFalse(app.Save());Assert.AreEqual(original,File.ReadAllText(path));Assert.IsTrue(app.TryReload());Assert.IsFalse(app.RecoveryRequired);Assert.AreEqual(123,app.Model.Snapshot.cash);Assert.IsTrue(app.Save());}
  [Test] public void ValidBackupStillRecoversExactProgress(){string backup=Good(234);File.WriteAllText(path,"broken primary");File.WriteAllText(path+".bak",backup);var app=new GameSession(new SaveStore(path,codec),new SeededRandom(1));Assert.IsFalse(app.RecoveryRequired);Assert.AreEqual(234,app.Model.Snapshot.cash);Assert.IsTrue(app.Save());Assert.AreEqual(234,new GameSession(new SaveStore(path,codec),new SeededRandom(1)).Model.Snapshot.cash);}
  [Test] public void MissingFilesAreAPlayableFreshProfile(){var app=new GameSession(new SaveStore(path,codec),new SeededRandom(1));Assert.IsFalse(app.RecoveryRequired);Assert.IsTrue(app.TryBeginSpin(out _));Assert.AreEqual(1,app.Model.Snapshot.spins);}
  [Test] public void ConfirmedFreshStartArchivesBothOriginalByteStreams(){File.WriteAllText(path,"old primary");File.WriteAllText(path+".bak","old backup");var app=new GameSession(new SaveStore(path,codec),new SeededRandom(1));Assert.IsTrue(app.TryReset());Assert.IsFalse(app.RecoveryRequired);Assert.AreEqual(3,app.Model.Snapshot.freeSpins);var archived=Directory.GetFiles(dir,"*.recovery-*").Select(File.ReadAllText).ToArray();CollectionAssert.AreEquivalent(new[]{"old primary","old backup"},archived);Assert.AreEqual(0,new GameSession(new SaveStore(path,codec),new SeededRandom(1)).Model.Snapshot.cash);}
  [Test] public void FreshStartFailsIfOriginalCannotBePreserved(){File.WriteAllText(path,"old primary");var app=new GameSession(new SaveStore(path,codec),new SeededRandom(1));using(var held=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.None)){Assert.IsFalse(app.TryReset());Assert.IsTrue(app.RecoveryRequired);}Assert.AreEqual("old primary",File.ReadAllText(path));Assert.IsFalse(app.Save());}
 }
}
